package validation

import (
	"errors"

	"fyne.io/fyne/v2"
)

// NewAllStrings creates a validator that checks if the input matches one of the allowed strings.
// Returns nil if valid, otherwise returns an error.
//
// Since: 2.5
func NewAllStrings(allowed []string) fyne.StringValidator {
	return func(text string) error {
		for _, s := range allowed {
			if text == s {
				return nil
			}
		}
		return errors.New("input does not match any allowed string")
	}
}

